-- Generated by tools/runtime/generate-food-allocation-migration.ts.
SET search_path=bitpos,public;
CREATE FUNCTION draft067_assert_allocations(merchant uuid,oid uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,bitpos,pg_temp AS $$
DECLARE f order_allocation_finalizations;a order_authority;d quote_delivery_snapshots;doc quote_configured_food;s food_shipments;driver uuid;
 item numeric;discount numeric;tax numeric;delivery numeric;service numeric;tip numeric;funding numeric;driver_fee numeric;
BEGIN
 SELECT * INTO STRICT a FROM order_authority WHERE merchant_id=merchant AND order_id=oid;
 SELECT * INTO f FROM order_allocation_finalizations WHERE merchant_id=merchant AND order_id=oid;
 IF NOT FOUND THEN RETURN; END IF; -- not yet finalized; delivered root requires it
 SELECT * INTO STRICT d FROM quote_delivery_snapshots WHERE merchant_id=merchant AND quote_id=a.quote_id;
 SELECT * INTO STRICT doc FROM quote_configured_food WHERE merchant_id=merchant AND quote_id=a.quote_id;
 SELECT * INTO STRICT s FROM food_shipments WHERE merchant_id=merchant AND order_id=oid;
 SELECT fa.driver_id INTO driver FROM food_assignments fa WHERE fa.shipment_id=s.id AND fa.state='DELIVERED';
 IF driver IS NULL AND (s.state<>'CANCELLED'
  OR NOT EXISTS(SELECT 1 FROM online_food_orders WHERE merchant_id=merchant AND order_id=oid AND acceptance_status IN('REJECTED','TIMED_OUT'))
  OR EXISTS(SELECT 1 FROM food_assignments WHERE shipment_id=s.id AND picked_up_at IS NOT NULL))
 THEN RAISE EXCEPTION 'ALLOCATION_FINALIZATION_REQUIRES_DELIVERY_OR_UNEARNED_REFUND' USING ERRCODE='23514'; END IF;
 IF (f.quote_id,f.currency,f.decimals,f.total_minor) IS DISTINCT FROM (a.quote_id,a.catalog_currency,a.catalog_decimals,a.total_minor)
 OR EXISTS(SELECT 1 FROM order_allocations x WHERE x.merchant_id=merchant AND x.order_id=oid
  AND (x.source_quote_id<>a.quote_id OR x.currency<>a.catalog_currency OR x.decimals<>a.catalog_decimals
   OR (x.party_kind='MERCHANT' AND x.party_id<>merchant)
   OR (x.party_kind='DRIVER' AND (driver IS NULL OR x.party_id<>driver OR x.kind NOT IN('DELIVERY','SERVICE')))
   OR (x.kind IN('ITEM','DISCOUNT') AND x.party_kind<>'MERCHANT')
   OR (x.kind IN('DELIVERY','SERVICE') AND x.party_kind NOT IN('MERCHANT','DRIVER','PLATFORM'))
   OR x.party_kind='CUSTOMER'))
 THEN RAISE EXCEPTION 'ALLOCATION_IDENTITY' USING ERRCODE='23514'; END IF;
 SELECT coalesce(sum(amount_minor) FILTER(WHERE kind='ITEM'),0),coalesce(sum(amount_minor) FILTER(WHERE kind='DISCOUNT'),0),
 coalesce(sum(amount_minor) FILTER(WHERE kind='TAX'),0),coalesce(sum(amount_minor) FILTER(WHERE kind='DELIVERY'),0),
 coalesce(sum(amount_minor) FILTER(WHERE kind='SERVICE'),0),coalesce(sum(amount_minor) FILTER(WHERE kind='TIP'),0),
 coalesce(sum(amount_minor) FILTER(WHERE kind='COUPON_FUNDING'),0),coalesce(sum(amount_minor) FILTER(WHERE party_kind='DRIVER'),0)
 INTO item,discount,tax,delivery,service,tip,funding,driver_fee FROM order_allocations WHERE merchant_id=merchant AND order_id=oid;
 IF item IS DISTINCT FROM (doc.snapshot->'subtotal'->>'amountMinor')::numeric
 OR discount IS DISTINCT FROM (doc.snapshot->'discount'->>'amountMinor')::numeric
 OR tax IS DISTINCT FROM (doc.snapshot->'tax'->>'amountMinor')::numeric
 OR delivery<>d.delivery_minor OR service<>d.service_minor OR tip<>0 OR funding<>0
 OR item-discount+tax+delivery+service+tip<>f.total_minor OR driver_fee<>(CASE WHEN driver IS NULL THEN 0 ELSE d.driver_minor END)
 THEN RAISE EXCEPTION 'FINAL_ALLOCATION_TOTALS' USING ERRCODE='23514'; END IF;
 -- Gross/discount allocations use the canonical configured line ID. Fee rows
 -- use the reserved line ID @fees. This makes net refund/payout caps exact.
 IF EXISTS(
  SELECT 1 FROM jsonb_array_elements(doc.snapshot->'lines') ln
  WHERE (SELECT coalesce(sum(x.amount_minor) FILTER(WHERE kind='ITEM'),0) FROM order_allocations x WHERE x.merchant_id=merchant AND x.order_id=oid AND x.line_id=ln->>'lineId')
    IS DISTINCT FROM (ln->'basePrice'->>'amountMinor')::numeric*(ln->>'qty')::numeric
  OR (SELECT coalesce(sum(x.amount_minor) FILTER(WHERE kind='DISCOUNT'),0) FROM order_allocations x WHERE x.merchant_id=merchant AND x.order_id=oid AND x.line_id=ln->>'lineId')
    IS DISTINCT FROM ((ln->'basePrice'->>'amountMinor')::numeric-(ln->'unitPrice'->>'amountMinor')::numeric)*(ln->>'qty')::numeric
 ) OR EXISTS(SELECT 1 FROM order_allocations x WHERE x.merchant_id=merchant AND x.order_id=oid
  AND ((x.kind IN('ITEM','DISCOUNT') AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(doc.snapshot->'lines') ln WHERE ln->>'lineId'=x.line_id))
   OR (x.kind IN('DELIVERY','SERVICE') AND x.line_id<>'@fees')))
 OR (SELECT coalesce(sum(amount_minor),0) FROM order_allocations WHERE merchant_id=merchant AND order_id=oid AND party_kind='MERCHANT' AND kind IN('DELIVERY','SERVICE'))<>d.merchant_minor
 OR (SELECT coalesce(sum(amount_minor),0) FROM order_allocations WHERE merchant_id=merchant AND order_id=oid AND party_kind='PLATFORM' AND kind IN('DELIVERY','SERVICE'))<>d.platform_minor+(CASE WHEN driver IS NULL THEN d.driver_minor ELSE 0 END)
 THEN RAISE EXCEPTION 'ALLOCATION_LINE_OR_FEE_PARTY_TOTALS' USING ERRCODE='23514'; END IF;
END $$;
CREATE FUNCTION food_allocation_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,bitpos,pg_temp AS $$
BEGIN
 PERFORM draft067_assert_allocations(NEW.merchant_id,NEW.order_id);RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER food_allocation_complete AFTER INSERT ON order_allocations DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION food_allocation_guard();
CREATE CONSTRAINT TRIGGER food_allocation_final_complete AFTER INSERT ON order_allocation_finalizations DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION food_allocation_guard();
CREATE FUNCTION food_allocation_seal() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,bitpos,pg_temp AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM order_allocation_finalizations WHERE merchant_id=NEW.merchant_id AND order_id=NEW.order_id AND posting_xid<>pg_current_xact_id()) THEN RAISE EXCEPTION 'ALLOCATION_ALREADY_FINALIZED' USING ERRCODE='23514';END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER food_allocation_sealed BEFORE INSERT ON order_allocations FOR EACH ROW EXECUTE FUNCTION food_allocation_seal();
REVOKE ALL ON FUNCTION draft067_assert_allocations(uuid,uuid),food_allocation_guard(),food_allocation_seal() FROM PUBLIC,bitpos_app;
